CREATE OR REPLACE TABLE materializer_assumption_check AS
WITH m AS (
  SELECT * FROM __meta_preview__
), p1 AS (
  SELECT 'table_1_preview' AS table, CAST(list_agg(value, ', ') AS TEXT) AS columns
  FROM (
    SELECT UNNEST(STRUCT_PACK(value := CAST(value AS VARCHAR))) FROM (
      SELECT * FROM preview1 LIMIT 0
    )
  )
), p2 AS (
  SELECT 'table_2_preview' AS table, CAST(list_agg(value, ', ') AS TEXT) AS columns
  FROM (
    SELECT UNNEST(STRUCT_PACK(value := CAST(value AS VARCHAR))) FROM (
      SELECT * FROM preview2 LIMIT 0
    )
  )
)
SELECT * FROM m
